    // Used as the "high nibble result" in the SIMD path and for scalar fallback.
    private static ReadOnlySpan<byte> NibbleReverseLo => [
        0x00, 0x08, 0x04, 0x0C, 0x02, 0x0A, 0x06, 0x0E,
        0x01, 0x09, 0x05, 0x0D, 0x03, 0x0B, 0x07, 0x0F
    ];

    private static ReadOnlySpan<byte> NibbleReverseHi => [
        0x00, 0x80, 0x40, 0xC0, 0x20, 0xA0, 0x60, 0xE0,
        0x10, 0x90, 0x50, 0xD0, 0x30, 0xB0, 0x70, 0xF0
    ];

    public static void ReverseInPlace(Span<byte> data)
    {
        // Strategy: reverse bits by splitting each byte into two nibbles,
        // using a shuffle LUT to reverse each nibble independently, then
        // combining: reversed_low_nibble goes to high bits and vice versa.

