                var lo = vec & mask;
                var hi = Vector512.ShiftRightLogical(vec.AsUInt16(), 4).AsByte() & mask;
                var result = Vector512.ShuffleUnsafe(hiLut, lo) | Vector512.ShuffleUnsafe(loLut, hi);
                result.StoreUnsafe(ref ptr, (nuint)i);
            }
