        {
            var loLut = Vector256.Create(NibbleReverseLo);
            var hiLut = Vector256.Create(NibbleReverseHi);
            var mask = Vector256.Create((byte)0x0F);

            int lastVec = data.Length - Vector256<byte>.Count;
            for (; i <= lastVec; i += Vector256<byte>.Count)
            {
                var vec = Vector256.LoadUnsafe(ref ptr, (nuint)i);
                var lo = vec & mask;
                var hi = Vector256.ShiftRightLogical(vec.AsUInt16(), 4).AsByte() & mask;
                var result = Vector256.ShuffleUnsafe(hiLut, lo) | Vector256.ShuffleUnsafe(loLut, hi);
                result.StoreUnsafe(ref ptr, (nuint)i);
            }
